INSERT INTO `wp_posts` ( `ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(159, 3, '2026-03-30 12:25:38', '2026-03-30 12:25:38', '<!-- wp:create-block/intro-block {"bodyText":"Chez Escouade, nous croyons que la réussite d\'un projet repose avant tout sur les personnes.\\u003cbr\\u003e\\u003cbr\\u003eBasée à Madagascar, notre société réunit des développeurs passionnés et les connecte à des projets stimulants portés par nos partenaires en Europe.\\u003cbr\\u003e"} -->\n<div class="block hero-intro-block bgi bgi--4 "><div class="hero-intro-block__content uk-container"><div class="hero-intro-block__body"><div class="card hero-intro-card"><div class="hero-intro-card__background scale-x-[-1]"></div><div class="hero-intro-card__content flex flex-col lg:flex-row-reverse"><div class="hero-intro-card__header"><figure class="img-container"><img src="http://picsum.photos/id/206/576/414.jpg" alt=""/></figure></div><div class="hero-intro-card__body"><div class="rte rte--em-c-2"><h2 class="title title--h1 c--3"><span>Envie de rejoindre <em>l\'Escouade</em> ?</span></h2><div class="text"><p>Chez Escouade, nous croyons que la réussite d\'un projet repose avant tout sur les personnes.<br><br>Basée à Madagascar, notre société réunit des développeurs passionnés et les connecte à des projets stimulants portés par nos partenaires en Europe.<br></p></div><div class="actions flex flex-col sm:flex-row md:flex-wrap items-stretch gap-[20px]"><a class="btn c--4 bgc--5-2 btn-shadow-sm w-a" href="#" title="Nos offres d\'emploi"><span>Nos offres d\'emploi</span></a><a class="btn c--1-2 bgc--1-2 bdc--1-2 btn-shadow-sm w-a" href="#" title="Candidature spontanée"><span>Candidature spontanée</span></a></div></div></div></div></div></div></div></div>\n<!-- /wp:create-block/intro-block -->\n\n<!-- wp:create-block/trust-block {"bodyText":"Notre motivation est de faire progresser nos équipes autant que nos clients.\\u003cbr\\u003eLe développement des compétences est un levier clé de performance."} -->\n<div class="block dna-block "><div class="dna-block__content uk-container flex flex-col gap-[64px]"><div class="dna-block__header text-center"><h2 class="title title--h2 c--2 rte--em-c-5 mb-0 text-[48px]">Notre <em>ADN</em></h2><p>Notre motivation est de faire progresser nos équipes autant que nos clients.<br>Le développement des compétences est un levier clé de performance.</p></div><div class="dna-block__body grid grid-cols-1 md:grid-cols-3 gap-[32px]"><!-- wp:create-block/trust-card {"headingText":"Engagé","bodyText":"Au service des clients et des coéquipiers","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-target.png","alt":"","id":128}} -->\n<div class="card dna-card flex-1 h-full "><div class="dna-card__content"><div class="dna-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-target.png" alt=""/></figure></div><div class="dna-card__body"><h3 class="title title--h3 c--2-5"><span>Engagé</span></h3><p>Au service des clients et des coéquipiers</p></div></div></div>\n<!-- /wp:create-block/trust-card -->\n\n<!-- wp:create-block/trust-card {"headingText":"Dynamique","bodyText":"Innovations portées par l’énergie collective","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-rocket.png","alt":"","id":129}} -->\n<div class="card dna-card flex-1 h-full "><div class="dna-card__content"><div class="dna-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-rocket.png" alt=""/></figure></div><div class="dna-card__body"><h3 class="title title--h3 c--2-5"><span>Dynamique</span></h3><p>Innovations portées par l’énergie collective</p></div></div></div>\n<!-- /wp:create-block/trust-card -->\n\n<!-- wp:create-block/trust-card {"headingText":"Solidaire","bodyText":"Soutien mutuel et esprit d’équipe","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-chain.png","alt":"","id":127}} -->\n<div class="card dna-card flex-1 h-full "><div class="dna-card__content"><div class="dna-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-chain.png" alt=""/></figure></div><div class="dna-card__body"><h3 class="title title--h3 c--2-5"><span>Solidaire</span></h3><p>Soutien mutuel et esprit d’équipe</p></div></div></div>\n<!-- /wp:create-block/trust-card --></div></div></div>\n<!-- /wp:create-block/trust-block -->\n\n<!-- wp:create-block/numbers-block -->\n<div class="block numbers-block bgi bgi--5"><div class="numbers-block__content uk-container text-center flex flex-col gap-[32px]"><div class="numbers-block__header"><h2 class="title title--h2 c--4 [&amp;_small]:font-500"><span>Quelques chiffres clés</span> <small><span>qui nous définissent</span></small></h2></div><div class="numbers-block__body"><div class="card numbers-card"><div class="numbers-card__content"><div class="numbers-card__body grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 w-full justify-between" data-uk-grid="margin: spacer;"><!-- wp:create-block/numbers-item {"value":"14","label":"Ans d\'expérience"} -->\n<h3 class="number "><div class="number-value"><span>14</span><sup><span>+</span></sup></div><div class="number-label"><span>Ans d\'expérience</span></div></h3>\n<!-- /wp:create-block/numbers-item -->\n\n<!-- wp:create-block/numbers-item {"value":"20","label":"Collaborateurs"} -->\n<h3 class="number "><div class="number-value"><span>20</span><sup><span>+</span></sup></div><div class="number-label"><span>Collaborateurs</span></div></h3>\n<!-- /wp:create-block/numbers-item -->\n\n<!-- wp:create-block/numbers-item {"value":"80","suffix":"%","label":"Satisfaction client"} -->\n<h3 class="number "><div class="number-value"><span>80</span><sup><span>%</span></sup></div><div class="number-label"><span>Satisfaction client</span></div></h3>\n<!-- /wp:create-block/numbers-item -->\n\n<!-- wp:create-block/numbers-item {"value":"200","label":"Projets réalisés"} -->\n<h3 class="number "><div class="number-value"><span>200</span><sup><span>+</span></sup></div><div class="number-label"><span>Projets réalisés</span></div></h3>\n<!-- /wp:create-block/numbers-item --></div></div></div></div></div></div>\n<!-- /wp:create-block/numbers-block -->\n\n<!-- wp:create-block/content-block -->\n<div class="wp-block-create-block-content-block"><div class="block bgi bgc--white edito-block"><div class="edito-block__content uk-container flex flex-col gap-[64px]"><div class="edito-block__header "><span class="title title--h2 rte rte--em-c-5 c--2">Pourquoi choisir <em>Escouade ?</em></span></div><div class="edito-block__body flex flex-col gap-[64px] sm:gap-[76px] md:gap-[88px] lg:gap-[100px]"><!-- wp:create-block/content-card {"headingText":"Une culture d’entreprise éthique et humaine","bodyText":"\\u003cp\\u003eEscouade cultive une approche éthique fondée sur la transparence, la responsabilité et le respect des personnes.\\u003c/p\\u003e\\u003cp\\u003eNous favorisons un environnement de travail bienveillant où chacun peut s’exprimer, évoluer et s’épanouir.\\u003c/p\\u003e\\u003cp\\u003eCette culture humaine renforce la cohésion des équipes et la qualité des projets que nous menons.\\u003c/p\\u003e","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-3.png","alt":"","id":108},"button":{"text":"Déposer ma candidature","url":"#","openInNewTab":false},"transparentBackground":false,"overline":{"show":true,"text":"Un cadre de travail respectueux"},"cardStyle":"3"} -->\n<div class="wp-block-create-block-content-card"><div class="block edito-card bgc bgc--4"><div class="edito-card__content flex flex-col md:flex-row"><div class="edito-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-3.png" alt=""/></figure></div><div class="edito-card__body"><div class="content"><ul class="taglist mb-0 flex flex-wrap gap-[10px] mb-[20px]"><li><span class="tag"><span>Un cadre de travail respectueux</span></span></li></ul><h2 class="title title--h3 c--5-2"><span>Une culture d’entreprise éthique et humaine</span></h2><div class="text"><div><p>Escouade cultive une approche éthique fondée sur la transparence, la responsabilité et le respect des personnes.</p><p>Nous favorisons un environnement de travail bienveillant où chacun peut s’exprimer, évoluer et s’épanouir.</p><p>Cette culture humaine renforce la cohésion des équipes et la qualité des projets que nous menons.</p></div></div><div class="actions"><a class="btn c--4 bgc--5 btn-shadow-sm" href="#" title="Déposer ma candidature"><span>Déposer ma candidature</span><i class="es-icon-chevron-right"></i></a></div></div></div></div></div></div>\n<!-- /wp:create-block/content-card -->\n\n<!-- wp:create-block/content-card {"headingText":"Un environnement professionnel sain et équilibré","bodyText":"\\u003cp\\u003eUn environnement professionnel sain est essentiel à la réussite collective.\\u003c/p\\u003e\\u003cp\\u003eNous valorisons l’équilibre entre vie professionnelle et vie personnelle tout en maintenant un haut niveau d’exigence.\\u003c/p\\u003e\\u003cp\\u003eCette philosophie permet à nos équipes de s’investir pleinement et durablement.\\u003c/p\\u003e","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-2.png","alt":"","id":107},"button":{"text":"Déposer ma candidature","url":"#","openInNewTab":false},"transparentBackground":false,"overline":{"show":true,"text":"Un environnement stimulant"},"cardStyle":"4"} -->\n<div class="wp-block-create-block-content-card"><div class="block edito-card bgc bgc--4"><div class="edito-card__content flex flex-col md:flex-row"><div class="edito-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-2.png" alt=""/></figure></div><div class="edito-card__body"><div class="content"><ul class="taglist mb-0 flex flex-wrap gap-[10px] mb-[20px]"><li><span class="tag"><span>Un environnement stimulant</span></span></li></ul><h2 class="title title--h3 c--2-1a"><span>Un environnement professionnel sain et équilibré</span></h2><div class="text"><div><p>Un environnement professionnel sain est essentiel à la réussite collective.</p><p>Nous valorisons l’équilibre entre vie professionnelle et vie personnelle tout en maintenant un haut niveau d’exigence.</p><p>Cette philosophie permet à nos équipes de s’investir pleinement et durablement.</p></div></div><div class="actions"><a class="btn c--4 bgc--5 btn-shadow-sm" href="#" title="Déposer ma candidature"><span>Déposer ma candidature</span><i class="es-icon-chevron-right"></i></a></div></div></div></div></div></div>\n<!-- /wp:create-block/content-card -->\n\n<!-- wp:create-block/content-card {"headingText":"Des conditions qui valorisent l’engagement et le potentiel","bodyText":"\\u003cp\\u003eNous croyons que le potentiel s’exprime pleinement lorsque les conditions sont réunies pour s’investir durablement.\\u003c/p\\u003e\\u003cp\\u003eEscouade offre un accompagnement personnalisé, des projets stimulants et une attention portée au bien-être professionnel.\\u003c/p\\u003e\\u003cp\\u003eCet équilibre favorise l’engagement et la performance sur le long terme.\\u003c/p\\u003e","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-3.png","alt":"","id":108},"button":{"text":"Déposer ma candidature","url":"#","openInNewTab":false},"transparentBackground":false,"overline":{"show":true,"text":"Un climat favorisant la motivation"},"cardStyle":"3"} -->\n<div class="wp-block-create-block-content-card"><div class="block edito-card bgc bgc--4"><div class="edito-card__content flex flex-col md:flex-row"><div class="edito-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-3.png" alt=""/></figure></div><div class="edito-card__body"><div class="content"><ul class="taglist mb-0 flex flex-wrap gap-[10px] mb-[20px]"><li><span class="tag"><span>Un climat favorisant la motivation</span></span></li></ul><h2 class="title title--h3 c--5-2"><span>Des conditions qui valorisent l’engagement et le potentiel</span></h2><div class="text"><div><p>Nous croyons que le potentiel s’exprime pleinement lorsque les conditions sont réunies pour s’investir durablement.</p><p>Escouade offre un accompagnement personnalisé, des projets stimulants et une attention portée au bien-être professionnel.</p><p>Cet équilibre favorise l’engagement et la performance sur le long terme.</p></div></div><div class="actions"><a class="btn c--4 bgc--5 btn-shadow-sm" href="#" title="Déposer ma candidature"><span>Déposer ma candidature</span><i class="es-icon-chevron-right"></i></a></div></div></div></div></div></div>\n<!-- /wp:create-block/content-card --></div></div></div></div>\n<!-- /wp:create-block/content-block -->\n\n<!-- wp:create-block/job-advertising-block -->\n<div class="wp-block-create-block-job-advertising-block"><div class="block bgi bgi--5 job-advertising-block"><div class="job-advertising-block__content uk-container flex gap-[70px] flex-col"><div class="block-header"><h2 class="title title--h2 rte rte--em-c-5 c--4 mb-0">Rejoignez votre Escouade</h2></div><div class="job-advertising-block__body" data-uk-slider="true"><div class="slider uk-slider-items"><!-- wp:create-block/job-advertising-card {"image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-1.png","alt":"","id":113}} -->\n<div class="slide card job-advertising-card "><div class="job-advertising-card__content c--4"><div class="card-header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/logo--text-iP-x-N5U.svg" alt="Escouade"/></figure></div><div class="job-advertising-card__body"><strong class="title--overline"><span>Nous recrutons</span></strong><h3 class="title color-inherit"><span>Technicien UI/UX Senior</span></h3><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-1.png" alt=""/></figure></div></div></div>\n<!-- /wp:create-block/job-advertising-card -->\n\n<!-- wp:create-block/job-advertising-card {"bodyText":"Développeur Back-end","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-2.png","alt":"","id":114}} -->\n<div class="slide card job-advertising-card "><div class="job-advertising-card__content c--4"><div class="card-header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/logo--text-iP-x-N5U.svg" alt="Escouade"/></figure></div><div class="job-advertising-card__body"><strong class="title--overline"><span>Nous recrutons</span></strong><h3 class="title color-inherit"><span>Développeur Back-end</span></h3><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-2.png" alt=""/></figure></div></div></div>\n<!-- /wp:create-block/job-advertising-card -->\n\n<!-- wp:create-block/job-advertising-card {"bodyText":"Directeur des opérations","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-3.png","alt":"","id":112}} -->\n<div class="slide card job-advertising-card "><div class="job-advertising-card__content c--4"><div class="card-header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/logo--text-iP-x-N5U.svg" alt="Escouade"/></figure></div><div class="job-advertising-card__body"><strong class="title--overline"><span>Nous recrutons</span></strong><h3 class="title color-inherit"><span>Directeur des opérations</span></h3><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-3.png" alt=""/></figure></div></div></div>\n<!-- /wp:create-block/job-advertising-card --></div></div><div class="job-advertising-block__footer flex justify-center"><a class="btn btn--lg c--4 bgc--5 btn-shadow-sm" href="#" title="Voir toutes les offres d\'emploi"><span>Voir toutes les offres d\'emploi</span><i class="es-icon-chevron-right"></i></a></div></div></div></div>\n<!-- /wp:create-block/job-advertising-block -->\n\n<!-- wp:create-block/talents-block -->\n<div class="block bgi bgc--white talents-block "><div class="talents-block__content uk-container flex flex-col gap-[70px]"><div class="talents-block__header"><h2 class="title title--h2 rte rte--em-c-5 c--2 mb-0">Rencontrez nos <em>talents</em></h2></div><div class="talents-block__body uk-child-width-1-1 uk-child-width-1-2@s uk-child-width-1-3@l uk-grid mx-[-16px] uk-slider-items"><!-- wp:create-block/talent-card {"firstname":"Minh","lastname":"Nguyên","role":"Lead Developer","quote":"J’aime l’équilibre entre autonomie et travail collectif.","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-1.png","alt":"","id":151}} -->\n<div class="card talent-card px-[16px] "><div class="talent-card__content"><div class="talent-card__header c--4 text-center"><h3 class="name title title--h3 c--4"><span class="firstname">Minh</span><span class="lastname">Nguyên</span></h3><div><span>Lead Developer</span></div></div><div class="talent-card__body"><div class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-1.png" alt=""/><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-1.png" alt=""/></div></div><div class="talent-card__footer"><blockquote><i class="es-icon-quotes"></i><div class="c--3"><span>J’aime l’équilibre entre autonomie et travail collectif.</span></div></blockquote></div></div></div>\n<!-- /wp:create-block/talent-card -->\n\n<!-- wp:create-block/talent-card {"firstname":"Nirina","lastname":"Rakotomalala","role":"QA Engineer","quote":"Comprendre les enjeux métiers est essentiel pour proposer les bonnes solutions","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-2.png","alt":"","id":152}} -->\n<div class="card talent-card px-[16px] "><div class="talent-card__content"><div class="talent-card__header c--4 text-center"><h3 class="name title title--h3 c--4"><span class="firstname">Nirina</span><span class="lastname">Rakotomalala</span></h3><div><span>QA Engineer</span></div></div><div class="talent-card__body"><div class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-2.png" alt=""/><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-2.png" alt=""/></div></div><div class="talent-card__footer"><blockquote><i class="es-icon-quotes"></i><div class="c--3"><span>Comprendre les enjeux métiers est essentiel pour proposer les bonnes solutions</span></div></blockquote></div></div></div>\n<!-- /wp:create-block/talent-card -->\n\n<!-- wp:create-block/talent-card {"firstname":"Thomas","lastname":"Leroy","role":"Développeur full stack","quote":"La confiance est un levier clé dans la réussite des projets.","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-3.png","alt":"","id":150}} -->\n<div class="card talent-card px-[16px] "><div class="talent-card__content"><div class="talent-card__header c--4 text-center"><h3 class="name title title--h3 c--4"><span class="firstname">Thomas</span><span class="lastname">Leroy</span></h3><div><span>Développeur full stack</span></div></div><div class="talent-card__body"><div class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-3.png" alt=""/><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-3.png" alt=""/></div></div><div class="talent-card__footer"><blockquote><i class="es-icon-quotes"></i><div class="c--3"><span>La confiance est un levier clé dans la réussite des projets.</span></div></blockquote></div></div></div>\n<!-- /wp:create-block/talent-card --></div></div></div>\n<!-- /wp:create-block/talents-block -->\n\n<!-- wp:create-block/cta-image-block {"image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/intro-img-1.png","alt":"","id":158}} -->\n<div class="block cta-image-block bgc bgc--3a "><div class="cta-image-block__content uk-container"><div class="cta-image-block__body"><div class="card cta-card"><div class="cta-card__background scale-x-[-1]"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/bg-6-CPDKQyS0.png" alt=""/></div><div class="cta-card__content flex flex-col-reverse md:flex-row-reverse"><div class="cta-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/intro-img-1.png" alt=""/><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/intro-img-1.png" alt=""/></figure></div><div class="cta-card__body"><div class="content"><h2 class="title title--h1 c--4"><span>Osez faire le premier pas</span></h2><div class="text"><p>Vous avez du potentiel, même sans offre publiée. Présentez votre profil et créez votre opportunité.</p></div><div class="actions flex flex-col sm:flex-row md:flex-wrap items-stretch gap-[20px]"><a class="btn btn--lg c--4 bgc--5 btn-shadow-sm" href="#" title="Candidature spontanée"><span>Candidature spontanée</span><i class="es-icon-chevron-right"></i></a></div></div></div></div></div></div></div></div>\n<!-- /wp:create-block/cta-image-block -->', 'Carrière', '', 'inherit', 'closed', 'closed', '', '121-revision-v1', '', '', '2026-03-30 12:25:38', '2026-03-30 12:25:38', '', 121, 'http://escouade.localhost:8080/?p=159', 0, 'revision', '', 0),
(163, 3, '2026-03-31 08:29:41', '2026-03-31 08:29:41', '<!-- wp:create-block/intro-block {"bodyText":"Chez Escouade, nous croyons que la réussite d\'un projet repose avant tout sur les personnes.\\u003cbr\\u003e\\u003cbr\\u003eBasée à Madagascar, notre société réunit des développeurs passionnés et les connecte à des projets stimulants portés par nos partenaires en Europe.\\u003cbr\\u003e"} -->\n<div class="block hero-intro-block bgi bgi--4 "><div class="hero-intro-block__content uk-container"><div class="hero-intro-block__body"><div class="card hero-intro-card"><div class="hero-intro-card__background scale-x-[-1]"></div><div class="hero-intro-card__content flex flex-col lg:flex-row-reverse"><div class="hero-intro-card__header"><figure class="img-container"><img src="http://picsum.photos/id/206/576/414.jpg" alt=""/></figure></div><div class="hero-intro-card__body"><div class="rte rte--em-c-2"><h2 class="title title--h1 c--3"><span>Envie de rejoindre <em>l\'Escouade</em> ?</span></h2><div class="text"><p>Chez Escouade, nous croyons que la réussite d\'un projet repose avant tout sur les personnes.<br><br>Basée à Madagascar, notre société réunit des développeurs passionnés et les connecte à des projets stimulants portés par nos partenaires en Europe.<br></p></div><div class="actions flex flex-col sm:flex-row md:flex-wrap items-stretch gap-[20px]"><a class="btn c--4 bgc--5-2 btn-shadow-sm w-a" href="#" title="Nos offres d\'emploi"><span>Nos offres d\'emploi</span></a><a class="btn c--1-2 bgc--1-2 bdc--1-2 btn-shadow-sm w-a" href="#" title="Candidature spontanée"><span>Candidature spontanée</span></a></div></div></div></div></div></div></div></div>\n<!-- /wp:create-block/intro-block -->\n\n<!-- wp:create-block/trust-block {"bodyText":"Notre motivation est de faire progresser nos équipes autant que nos clients.\\u003cbr\\u003eLe développement des compétences est un levier clé de performance."} -->\n<div class="block dna-block "><div class="dna-block__content uk-container flex flex-col gap-[64px]"><div class="dna-block__header text-center"><h2 class="title title--h2 c--2 rte--em-c-5 mb-0 text-[48px]">Notre <em>ADN</em></h2><p>Notre motivation est de faire progresser nos équipes autant que nos clients.<br>Le développement des compétences est un levier clé de performance.</p></div><div class="dna-block__body grid grid-cols-1 md:grid-cols-3 gap-[32px]"><!-- wp:create-block/trust-card {"headingText":"Engagé","bodyText":"Au service des clients et des coéquipiers","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-target.png","alt":"","id":128}} -->\n<div class="card dna-card flex-1 h-full "><div class="dna-card__content"><div class="dna-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-target.png" alt=""/></figure></div><div class="dna-card__body"><h3 class="title title--h3 c--2-5"><span>Engagé</span></h3><p>Au service des clients et des coéquipiers</p></div></div></div>\n<!-- /wp:create-block/trust-card -->\n\n<!-- wp:create-block/trust-card {"headingText":"Dynamique","bodyText":"Innovations portées par l’énergie collective","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-rocket.png","alt":"","id":129}} -->\n<div class="card dna-card flex-1 h-full "><div class="dna-card__content"><div class="dna-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-rocket.png" alt=""/></figure></div><div class="dna-card__body"><h3 class="title title--h3 c--2-5"><span>Dynamique</span></h3><p>Innovations portées par l’énergie collective</p></div></div></div>\n<!-- /wp:create-block/trust-card -->\n\n<!-- wp:create-block/trust-card {"headingText":"Solidaire","bodyText":"Soutien mutuel et esprit d’équipe","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-chain.png","alt":"","id":127}} -->\n<div class="card dna-card flex-1 h-full "><div class="dna-card__content"><div class="dna-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/dna-chain.png" alt=""/></figure></div><div class="dna-card__body"><h3 class="title title--h3 c--2-5"><span>Solidaire</span></h3><p>Soutien mutuel et esprit d’équipe</p></div></div></div>\n<!-- /wp:create-block/trust-card --></div></div></div>\n<!-- /wp:create-block/trust-block -->\n\n<!-- wp:create-block/numbers-block -->\n<div class="block numbers-block bgi bgi--5"><div class="numbers-block__content uk-container text-center flex flex-col gap-[32px]"><div class="numbers-block__header"><h2 class="title title--h2 c--4 [&amp;_small]:font-500"><span>Quelques chiffres clés</span> <small><span>qui nous définissent</span></small></h2></div><div class="numbers-block__body"><div class="card numbers-card"><div class="numbers-card__content"><div class="numbers-card__body grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 w-full justify-between" data-uk-grid="margin: spacer;"><!-- wp:create-block/numbers-item {"value":"14","label":"Ans d\'expérience"} -->\n<h3 class="number "><div class="number-value"><span>14</span><sup><span>+</span></sup></div><div class="number-label"><span>Ans d\'expérience</span></div></h3>\n<!-- /wp:create-block/numbers-item -->\n\n<!-- wp:create-block/numbers-item {"value":"20","label":"Collaborateurs"} -->\n<h3 class="number "><div class="number-value"><span>20</span><sup><span>+</span></sup></div><div class="number-label"><span>Collaborateurs</span></div></h3>\n<!-- /wp:create-block/numbers-item -->\n\n<!-- wp:create-block/numbers-item {"value":"80","suffix":"%","label":"Satisfaction client"} -->\n<h3 class="number "><div class="number-value"><span>80</span><sup><span>%</span></sup></div><div class="number-label"><span>Satisfaction client</span></div></h3>\n<!-- /wp:create-block/numbers-item -->\n\n<!-- wp:create-block/numbers-item {"value":"200","label":"Projets réalisés"} -->\n<h3 class="number "><div class="number-value"><span>200</span><sup><span>+</span></sup></div><div class="number-label"><span>Projets réalisés</span></div></h3>\n<!-- /wp:create-block/numbers-item --></div></div></div></div></div></div>\n<!-- /wp:create-block/numbers-block -->\n\n<!-- wp:create-block/content-block -->\n<div class="wp-block-create-block-content-block"><div class="block bgi bgc--white edito-block"><div class="edito-block__content uk-container flex flex-col gap-[64px]"><div class="edito-block__header "><span class="title title--h2 rte rte--em-c-5 c--2">Pourquoi choisir <em>Escouade ?</em></span></div><div class="edito-block__body flex flex-col gap-[64px] sm:gap-[76px] md:gap-[88px] lg:gap-[100px]"><!-- wp:create-block/content-card {"headingText":"Une culture d’entreprise éthique et humaine","bodyText":"\\u003cp\\u003eEscouade cultive une approche éthique fondée sur la transparence, la responsabilité et le respect des personnes.\\u003c/p\\u003e\\u003cp\\u003eNous favorisons un environnement de travail bienveillant où chacun peut s’exprimer, évoluer et s’épanouir.\\u003c/p\\u003e\\u003cp\\u003eCette culture humaine renforce la cohésion des équipes et la qualité des projets que nous menons.\\u003c/p\\u003e","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-3.png","alt":"","id":108},"button":{"text":"Déposer ma candidature","url":"#","openInNewTab":false},"transparentBackground":false,"overline":{"show":true,"text":"Un cadre de travail respectueux"}} -->\n<div class="wp-block-create-block-content-card"><div class="block edito-card bgc bgc--4"><div class="edito-card__content flex flex-col md:flex-row"><div class="edito-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-3.png" alt=""/></figure></div><div class="edito-card__body"><div class="content"><ul class="taglist mb-0 flex flex-wrap gap-[10px] mb-[20px]"><li><span class="tag"><span>Un cadre de travail respectueux</span></span></li></ul><h2 class="title title--h3 c--1a"><span>Une culture d’entreprise éthique et humaine</span></h2><div class="text"><div><p>Escouade cultive une approche éthique fondée sur la transparence, la responsabilité et le respect des personnes.</p><p>Nous favorisons un environnement de travail bienveillant où chacun peut s’exprimer, évoluer et s’épanouir.</p><p>Cette culture humaine renforce la cohésion des équipes et la qualité des projets que nous menons.</p></div></div><div class="actions"><a class="btn c--4 bgc--5 btn-shadow-sm" href="#" title="Déposer ma candidature"><span>Déposer ma candidature</span><i class="es-icon-chevron-right"></i></a></div></div></div></div></div></div>\n<!-- /wp:create-block/content-card -->\n\n<!-- wp:create-block/content-card {"headingText":"Un environnement professionnel sain et équilibré","bodyText":"\\u003cp\\u003eUn environnement professionnel sain est essentiel à la réussite collective.\\u003c/p\\u003e\\u003cp\\u003eNous valorisons l’équilibre entre vie professionnelle et vie personnelle tout en maintenant un haut niveau d’exigence.\\u003c/p\\u003e\\u003cp\\u003eCette philosophie permet à nos équipes de s’investir pleinement et durablement.\\u003c/p\\u003e","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-2.png","alt":"","id":107},"button":{"text":"Déposer ma candidature","url":"#","openInNewTab":false},"transparentBackground":false,"overline":{"show":true,"text":"Un environnement stimulant"}} -->\n<div class="wp-block-create-block-content-card"><div class="block edito-card bgc bgc--4"><div class="edito-card__content flex flex-col md:flex-row"><div class="edito-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-2.png" alt=""/></figure></div><div class="edito-card__body"><div class="content"><ul class="taglist mb-0 flex flex-wrap gap-[10px] mb-[20px]"><li><span class="tag"><span>Un environnement stimulant</span></span></li></ul><h2 class="title title--h3 c--1a"><span>Un environnement professionnel sain et équilibré</span></h2><div class="text"><div><p>Un environnement professionnel sain est essentiel à la réussite collective.</p><p>Nous valorisons l’équilibre entre vie professionnelle et vie personnelle tout en maintenant un haut niveau d’exigence.</p><p>Cette philosophie permet à nos équipes de s’investir pleinement et durablement.</p></div></div><div class="actions"><a class="btn c--4 bgc--5 btn-shadow-sm" href="#" title="Déposer ma candidature"><span>Déposer ma candidature</span><i class="es-icon-chevron-right"></i></a></div></div></div></div></div></div>\n<!-- /wp:create-block/content-card -->\n\n<!-- wp:create-block/content-card {"headingText":"Des conditions qui valorisent l’engagement et le potentiel","bodyText":"\\u003cp\\u003eNous croyons que le potentiel s’exprime pleinement lorsque les conditions sont réunies pour s’investir durablement.\\u003c/p\\u003e\\u003cp\\u003eEscouade offre un accompagnement personnalisé, des projets stimulants et une attention portée au bien-être professionnel.\\u003c/p\\u003e\\u003cp\\u003eCet équilibre favorise l’engagement et la performance sur le long terme.\\u003c/p\\u003e","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-3.png","alt":"","id":108},"button":{"text":"Déposer ma candidature","url":"#","openInNewTab":false},"transparentBackground":false,"overline":{"show":true,"text":"Un climat favorisant la motivation"}} -->\n<div class="wp-block-create-block-content-card"><div class="block edito-card bgc bgc--4"><div class="edito-card__content flex flex-col md:flex-row"><div class="edito-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/edito-img-3.png" alt=""/></figure></div><div class="edito-card__body"><div class="content"><ul class="taglist mb-0 flex flex-wrap gap-[10px] mb-[20px]"><li><span class="tag"><span>Un climat favorisant la motivation</span></span></li></ul><h2 class="title title--h3 c--1a"><span>Des conditions qui valorisent l’engagement et le potentiel</span></h2><div class="text"><div><p>Nous croyons que le potentiel s’exprime pleinement lorsque les conditions sont réunies pour s’investir durablement.</p><p>Escouade offre un accompagnement personnalisé, des projets stimulants et une attention portée au bien-être professionnel.</p><p>Cet équilibre favorise l’engagement et la performance sur le long terme.</p></div></div><div class="actions"><a class="btn c--4 bgc--5 btn-shadow-sm" href="#" title="Déposer ma candidature"><span>Déposer ma candidature</span><i class="es-icon-chevron-right"></i></a></div></div></div></div></div></div>\n<!-- /wp:create-block/content-card --></div></div></div></div>\n<!-- /wp:create-block/content-block -->\n\n<!-- wp:create-block/job-advertising-block -->\n<div class="wp-block-create-block-job-advertising-block"><div class="block bgi bgi--5 job-advertising-block"><div class="job-advertising-block__content uk-container flex gap-[70px] flex-col"><div class="block-header"><h2 class="title title--h2 rte rte--em-c-5 c--4 mb-0">Rejoignez votre Escouade</h2></div><div class="job-advertising-block__body" data-uk-slider="true"><div class="slider uk-slider-items"><!-- wp:create-block/job-advertising-card {"image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-1.png","alt":"","id":113}} -->\n<div class="slide card job-advertising-card "><div class="job-advertising-card__content c--4"><div class="card-header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/logo--text-iP-x-N5U.svg" alt="Escouade"/></figure></div><div class="job-advertising-card__body"><strong class="title--overline"><span>Nous recrutons</span></strong><h3 class="title color-inherit"><span>Technicien UI/UX Senior</span></h3><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-1.png" alt=""/></figure></div></div></div>\n<!-- /wp:create-block/job-advertising-card -->\n\n<!-- wp:create-block/job-advertising-card {"bodyText":"Développeur Back-end","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-2.png","alt":"","id":114}} -->\n<div class="slide card job-advertising-card "><div class="job-advertising-card__content c--4"><div class="card-header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/logo--text-iP-x-N5U.svg" alt="Escouade"/></figure></div><div class="job-advertising-card__body"><strong class="title--overline"><span>Nous recrutons</span></strong><h3 class="title color-inherit"><span>Développeur Back-end</span></h3><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-2.png" alt=""/></figure></div></div></div>\n<!-- /wp:create-block/job-advertising-card -->\n\n<!-- wp:create-block/job-advertising-card {"bodyText":"Directeur des opérations","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-3.png","alt":"","id":112}} -->\n<div class="slide card job-advertising-card "><div class="job-advertising-card__content c--4"><div class="card-header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/logo--text-iP-x-N5U.svg" alt="Escouade"/></figure></div><div class="job-advertising-card__body"><strong class="title--overline"><span>Nous recrutons</span></strong><h3 class="title color-inherit"><span>Directeur des opérations</span></h3><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-3.png" alt=""/></figure></div></div></div>\n<!-- /wp:create-block/job-advertising-card --></div></div><div class="job-advertising-block__footer flex justify-center"><a class="btn btn--lg c--4 bgc--5 btn-shadow-sm" href="#" title="Voir toutes les offres d\'emploi"><span>Voir toutes les offres d\'emploi</span><i class="es-icon-chevron-right"></i></a></div></div></div></div>\n<!-- /wp:create-block/job-advertising-block -->\n\n<!-- wp:create-block/talents-block -->\n<div class="block bgi bgc--white talents-block "><div class="talents-block__content uk-container flex flex-col gap-[70px]"><div class="talents-block__header"><h2 class="title title--h2 rte rte--em-c-5 c--2 mb-0">Rencontrez nos <em>talents</em></h2></div><div class="talents-block__body uk-child-width-1-1 uk-child-width-1-2@s uk-child-width-1-3@l uk-grid mx-[-16px] uk-slider-items"><!-- wp:create-block/talent-card {"firstname":"Minh","lastname":"Nguyên","role":"Lead Developer","quote":"J’aime l’équilibre entre autonomie et travail collectif.","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-1.png","alt":"","id":151}} -->\n<div class="card talent-card px-[16px] "><div class="talent-card__content"><div class="talent-card__header c--4 text-center"><h3 class="name title title--h3 c--4"><span class="firstname">Minh</span><span class="lastname">Nguyên</span></h3><div><span>Lead Developer</span></div></div><div class="talent-card__body"><div class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-1.png" alt=""/><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-1.png" alt=""/></div></div><div class="talent-card__footer"><blockquote><i class="es-icon-quotes"></i><div class="c--3"><span>J’aime l’équilibre entre autonomie et travail collectif.</span></div></blockquote></div></div></div>\n<!-- /wp:create-block/talent-card -->\n\n<!-- wp:create-block/talent-card {"firstname":"Nirina","lastname":"Rakotomalala","role":"QA Engineer","quote":"Comprendre les enjeux métiers est essentiel pour proposer les bonnes solutions","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-2.png","alt":"","id":152}} -->\n<div class="card talent-card px-[16px] "><div class="talent-card__content"><div class="talent-card__header c--4 text-center"><h3 class="name title title--h3 c--4"><span class="firstname">Nirina</span><span class="lastname">Rakotomalala</span></h3><div><span>QA Engineer</span></div></div><div class="talent-card__body"><div class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-2.png" alt=""/><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-2.png" alt=""/></div></div><div class="talent-card__footer"><blockquote><i class="es-icon-quotes"></i><div class="c--3"><span>Comprendre les enjeux métiers est essentiel pour proposer les bonnes solutions</span></div></blockquote></div></div></div>\n<!-- /wp:create-block/talent-card -->\n\n<!-- wp:create-block/talent-card {"firstname":"Thomas","lastname":"Leroy","role":"Développeur full stack","quote":"La confiance est un levier clé dans la réussite des projets.","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-3.png","alt":"","id":150}} -->\n<div class="card talent-card px-[16px] "><div class="talent-card__content"><div class="talent-card__header c--4 text-center"><h3 class="name title title--h3 c--4"><span class="firstname">Thomas</span><span class="lastname">Leroy</span></h3><div><span>Développeur full stack</span></div></div><div class="talent-card__body"><div class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-3.png" alt=""/><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/talent-profile-3.png" alt=""/></div></div><div class="talent-card__footer"><blockquote><i class="es-icon-quotes"></i><div class="c--3"><span>La confiance est un levier clé dans la réussite des projets.</span></div></blockquote></div></div></div>\n<!-- /wp:create-block/talent-card --></div></div></div>\n<!-- /wp:create-block/talents-block -->\n\n<!-- wp:create-block/cta-image-block {"image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/intro-img-1.png","alt":"","id":158}} -->\n<div class="block cta-image-block bgc bgc--3a "><div class="cta-image-block__content uk-container"><div class="cta-image-block__body"><div class="card cta-card"><div class="cta-card__background scale-x-[-1]"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/bg-6-CPDKQyS0.png" alt=""/></div><div class="cta-card__content flex flex-col-reverse md:flex-row-reverse"><div class="cta-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/intro-img-1.png" alt=""/><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/intro-img-1.png" alt=""/></figure></div><div class="cta-card__body"><div class="content"><h2 class="title title--h1 c--4"><span>Osez faire le premier pas</span></h2><div class="text"><p>Vous avez du potentiel, même sans offre publiée. Présentez votre profil et créez votre opportunité.</p></div><div class="actions flex flex-col sm:flex-row md:flex-wrap items-stretch gap-[20px]"><a class="btn btn--lg c--4 bgc--5 btn-shadow-sm" href="#" title="Candidature spontanée"><span>Candidature spontanée</span><i class="es-icon-chevron-right"></i></a></div></div></div></div></div></div></div></div>\n<!-- /wp:create-block/cta-image-block -->', 'Carrière', '', 'inherit', 'closed', 'closed', '', '121-revision-v1', '', '', '2026-03-31 08:29:41', '2026-03-31 08:29:41', '', 121, 'http://escouade.localhost:8080/?p=163', 0, 'revision', '', 0),
(164, 2, '2026-03-31 08:37:25', '2026-03-31 08:37:25', '<!-- wp:create-block/job-content-block -->\n<!-- wp:create-block/job-content-card {"sectionHeading":"À propos du poste"} -->\n<article class="flex flex-col gap-[32px] "><h2 class="title title--h3 c--2-1a"><span>À propos du poste</span></h2><div class="text rte"><!-- wp:paragraph -->\n<p>Nous recherchons un Développeur Talend ESB / Runtime pour renforcer notre équipe technique.<br>Vous interviendrez sur des flux d’échange et des architectures d’intégration, dans un environnement orienté performance et fiabilité.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Vous travaillerez en collaboration avec les équipes techniques et métiers afin de connecter les systèmes, structurer les échanges de données et garantir la qualité des flux.</p>\n<!-- /wp:paragraph --></div></article>\n<!-- /wp:create-block/job-content-card -->\n\n<!-- wp:create-block/job-content-card {"sectionHeading":"Vos missions principales"} -->\n<article class="flex flex-col gap-[32px] "><h2 class="title title--h3 c--2-1a"><span>Vos missions principales</span></h2><div class="text rte"><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>Concevoir, développer et maintenir des flux d’intégration avec Talend ESB / Runtime</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Mettre en place et maintenir des Webservices (SOAP et REST)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Assurer l’intégration et la communication entre différents systèmes</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Participer à l’optimisation des performances et à la fiabilité des flux</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Contribuer aux pipelines CI/CD liés aux déploiements</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Collaborer avec les équipes techniques pour répondre aux besoins métiers</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Participer à l’amélioration continue et à la documentation technique</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></article>\n<!-- /wp:create-block/job-content-card -->\n\n<!-- wp:create-block/job-content-card {"sectionHeading":"Profil recherché"} -->\n<article class="flex flex-col gap-[32px] "><h2 class="title title--h3 c--2-1a"><span>Profil recherché</span></h2><div class="text rte"><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li> Minimum 2 ans d’expérience sur Talend</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Mettre en place et maintenir des Webservices (SOAP et REST)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bonne maîtrise des Webservices (SOAP, REST, API)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Connaissance des environnements CI/CD</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Capacité à travailler en équipe et à être force de proposition</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Autonomie, rigueur et sens des responsabilités</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>CV et prétentions à envoyer à recrutement@escouade.mg</p>\n<!-- /wp:paragraph --></div></article>\n<!-- /wp:create-block/job-content-card -->\n<!-- /wp:create-block/job-content-block -->', 'Développeur Talend', '', 'publish', 'closed', 'closed', '', 'developpeur-talend', '', '', '2026-04-10 06:21:20', '2026-04-10 06:21:20', '', 0, 'http://escouade.localhost:8080/?post_type=job-offer&#038;p=164', 0, 'job-offer', '', 0) ;
INSERT INTO `wp_posts` ( `ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(167, 3, '2026-03-31 12:37:30', '2026-03-31 12:37:30', '<!-- wp:heading -->\n<h2 class="wp-block-heading">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>Our website address is: http://escouade.localhost:8080.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: http://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n', 'Privacy Policy', '', 'inherit', 'closed', 'closed', '', '3-revision-v1', '', '', '2026-03-31 12:37:30', '2026-03-31 12:37:30', '', 3, 'http://escouade.localhost:8080/?p=167', 0, 'revision', '', 0),
