(278, 3, '2026-04-06 21:15:07', '2026-04-06 21:15:07', '<!-- wp:create-block/job-advertising-block {"button":{"text":"Voir toutes les offres d\'emploi","url":"","openInNewTab":false}} -->\n<div id="join-your-squad" class="wp-block-create-block-job-advertising-block"><div class="block bgi bgi--5 job-advertising-block"><div class="job-advertising-block__content uk-container flex gap-[70px] flex-col"><div class="block-header"><h2 class="title title--h2 rte rte--em-c-5 c--4 mb-0">Rejoignez votre Escouade</h2></div><div class="job-advertising-block__body" data-uk-slider="true"><div class="slider uk-slider-items"><!-- wp:create-block/job-advertising-card {"bodyText":"Développeur Talend","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-1.png","alt":"","id":113},"url":"http://escouade.localhost:8080/job-offer/developpeur-talend/"} -->\n<div class="slide card job-advertising-card "><a href="http://escouade.localhost:8080/job-offer/developpeur-talend/" class="job-advertising-card__content c--4"><div class="job-advertising-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/logo--text-CPTW0Od3.svg" alt="Escouade"/></figure></div><div class="job-advertising-card__body"><strong class="title--overline"><span>Nous recrutons</span></strong><h3 class="title color-inherit"><span>Développeur Talend</span></h3><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-1.png" alt=""/></figure></div></a></div>\n<!-- /wp:create-block/job-advertising-card --></div></div><div class="job-advertising-block__footer flex justify-center"></div></div></div></div>\n<!-- /wp:create-block/job-advertising-block -->', 'Join your squad', '', 'publish', 'closed', 'closed', '', 'join-your-squad', '', '', '2026-04-06 21:15:07', '2026-04-06 21:15:07', '', 0, 'http://escouade.localhost:8080/join-your-squad/', 0, 'wp_block', '', 0) ;
