(390, 3, '2026-04-26 12:59:30', '2026-04-26 12:59:30', '<!-- wp:create-block/job-advertising-block {"button":{"text":"Voir toutes les offres d\'emploi","url":"","openInNewTab":false}} -->\n<div id="je-cherche-un-job" class="wp-block-create-block-job-advertising-block"><div class="block bgi bgi--5 job-advertising-block"><div class="job-advertising-block__content uk-container flex gap-[70px] flex-col"><div class="block-header"><h2 class="title title--h2 rte rte--em-c-5 c--4 mb-0">Rejoignez votre Escouade</h2></div><div class="job-advertising-block__body" data-uk-slider="true"><div class="slider uk-slider-items"><!-- wp:create-block/job-advertising-card {"bodyText":"Développeur Talend","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-1.png","alt":"","id":113},"url":"http://escouade.localhost:8080/offres-d-emploi/developpeur-talend/"} -->\n<div class="slide card job-advertising-card "><a href="http://escouade.localhost:8080/offres-d-emploi/developpeur-talend/" class="job-advertising-card__content c--4"><div class="job-advertising-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/logo--text-CPTW0Od3.svg" alt="Escouade"/></figure></div><div class="job-advertising-card__body"><strong class="title--overline"><span>Nous recrutons</span></strong><h3 class="title color-inherit"><span>Développeur Talend</span></h3><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-1.png" alt=""/></figure></div></a></div>\n<!-- /wp:create-block/job-advertising-card -->\n\n<!-- wp:create-block/job-advertising-card {"bodyText":"Selenium / tests autos","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-2.png","alt":"","id":114},"url":"http://escouade.localhost:8080/offres-d-emploi/selenium-tests-autos/"} -->\n<div class="slide card job-advertising-card "><a href="http://escouade.localhost:8080/offres-d-emploi/selenium-tests-autos/" class="job-advertising-card__content c--4"><div class="job-advertising-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/logo--text-CPTW0Od3.svg" alt="Escouade"/></figure></div><div class="job-advertising-card__body"><strong class="title--overline"><span>Nous recrutons</span></strong><h3 class="title color-inherit"><span>Selenium / tests autos</span></h3><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-2.png" alt=""/></figure></div></a></div>\n<!-- /wp:create-block/job-advertising-card -->\n\n<!-- wp:create-block/job-advertising-card {"bodyText":"Product Owner confirmé","image":{"url":"http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-3.png","alt":"","id":112},"url":"http://escouade.localhost:8080/offres-d-emploi/product-owner-confirme/"} -->\n<div class="slide card job-advertising-card "><a href="http://escouade.localhost:8080/offres-d-emploi/product-owner-confirme/" class="job-advertising-card__content c--4"><div class="job-advertising-card__header"><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/themes/aura/public/build/assets/logo--text-CPTW0Od3.svg" alt="Escouade"/></figure></div><div class="job-advertising-card__body"><strong class="title--overline"><span>Nous recrutons</span></strong><h3 class="title color-inherit"><span>Product Owner confirmé</span></h3><figure class="img-container"><img src="http://escouade.localhost:8080/wp-content/uploads/2026/03/job-advertising-img-3.png" alt=""/></figure></div></a></div>\n<!-- /wp:create-block/job-advertising-card --></div></div><div class="job-advertising-block__footer flex justify-center"></div></div></div></div>\n<!-- /wp:create-block/job-advertising-block -->', 'Join your squad', '', 'inherit', 'closed', 'closed', '', '319-revision-v1', '', '', '2026-04-26 12:59:30', '2026-04-26 12:59:30', '', 319, 'http://escouade.localhost:8080/?p=390', 0, 'revision', '', 0) ;
INSERT INTO `wp_posts` ( `ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(392, 2, '2026-05-29 07:11:04', '2026-05-29 07:11:04', '<!-- wp:create-block/job-content-block -->\n<!-- wp:create-block/job-content-card {"sectionHeading":"À propos du poste"} -->\n<article class="flex flex-col gap-[32px] "><h2 class="title title--h3 c--2-1a"><span>À propos du poste</span></h2><div class="text rte"><!-- wp:paragraph {"align":"left"} -->\n<p class="has-text-align-left">Nous recherchons un(e) <strong>Business Developer IT / ESN expérimenté(e)</strong> pour accompagner le développement commercial d’Escouade.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"align":"left"} -->\n<p class="has-text-align-left">L’objectif : identifier de nouveaux clients et développer des opportunités commerciales en Europe et à Madagascar autour de nos activités IT.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Nous ne recherchons pas un profil qui attend une liste de leads : la prospection, l\'ouverture de comptes et le développement d\'opportunités font pleinement partie du rôle.</p>\n<!-- /wp:paragraph --></div></article>\n<!-- /wp:create-block/job-content-card -->\n\n<!-- wp:create-block/job-content-card {"sectionHeading":"Vos missions principales"} -->\n<article class="flex flex-col gap-[32px] "><h2 class="title title--h3 c--2-1a"><span>Vos missions principales</span></h2><div class="text rte"><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>Prospecter et ouvrir de nouveaux comptes de manière autonome</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Identifier des besoins en développement, renfort d’équipes ou accompagnement IT</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Créer et développer son propre réseau</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Echanger avec des décideurs et interlocuteurs projets</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Faire avancer les discussions commerciales dans la durée</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></article>\n<!-- /wp:create-block/job-content-card -->\n\n<!-- wp:create-block/job-content-card {"sectionHeading":"Profil recherché"} -->\n<article class="flex flex-col gap-[32px] "><h2 class="title title--h3 c--2-1a"><span>Profil recherché</span></h2><div class="text rte"><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>Profil senior avec expérience en ESN / services IT</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Solide expérience en prospection et ouverture de comptes</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Capacité à développer son propre réseau et générer des opportunités</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Aisance avec les décideurs métiers et techniques</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Autonomie, sens du résultat et excellent relationnel</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Français courant, anglais apprécié</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>CV et prétentions à envoyer à <a href="mailto:recrutement@escouade.mg">recrutement@escouade.mg</a></p>\n<!-- /wp:paragraph --></div></article>\n<!-- /wp:create-block/job-content-card -->\n<!-- /wp:create-block/job-content-block -->', 'Business Developer IT', '', 'publish', 'closed', 'closed', '', 'business-developer-it', '', '', '2026-05-29 07:11:05', '2026-05-29 07:11:05', '', 0, 'http://escouade.localhost:8080/?post_type=job-offer&#038;p=392', 0, 'job-offer', '', 0),
